contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 dummy) public payable {
        address before = c.owner(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.owned(); if (__ESBMC_reverted()) return;
        reverted = false;
        address afterVal = c.owner(); if (__ESBMC_reverted()) return;
        assert(afterVal == before);
    }

    receive() external payable {}
}

