pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(uint256 dummy) internal {
        address before;
        try c.owner() returns (address __r) { before = __r; } catch { return; }
        bool reverted;
        try c.owned() {} catch { return; }
        reverted = false;
        address afterVal;
        try c.owner() returns (address __r) { afterVal = __r; } catch { return; }
        assertTrue(afterVal == before);
    }

    function testFuzz_run(uint256 dummy) public {
        _run(dummy);
    }

    receive() external payable {}
}
